import{_ as i,o as n,c as a,ai as p}from"./chunks/framework.BxxKhjs3.js";const l="/pub-blog/assets/phone.ChxzDij2.gif",e="/pub-blog/assets/foldable.DQarqGqA.gif",t="/pub-blog/assets/tablet.76kQuTyV.gif",h="/pub-blog/assets/image-20250313084849947.C3lcY-TT.png",u=JSON.parse('{"title":"01-万少带你精读鸿蒙codelabs 一多界面适配和三层架构","description":"","frontmatter":{},"headers":[],"relativePath":"万少带你精读鸿蒙codelabs/01-万少带你精读鸿蒙codelabs 一多界面适配和三层架构/01-万少带你精读鸿蒙codelabs 一多界面适配和三层架构.md","filePath":"万少带你精读鸿蒙codelabs/01-万少带你精读鸿蒙codelabs 一多界面适配和三层架构/01-万少带你精读鸿蒙codelabs 一多界面适配和三层架构.md","lastUpdated":1741827237000,"__rawMarkdown":"# 01-万少带你精读鸿蒙codelabs 一多界面适配和三层架构\\n\\n## 前言\\n\\n本文将深入解析华为开发者联盟 CodeLabs 上的优质一多开发示例项目——MultiShopping。该项目展示了鸿蒙应用开发中的最佳实践，特别是在响应式布局和工程级一多架构方面的实现。项目地址：[https://developer.huawei.com/consumer/cn/codelabsPortal/carddetails/tutorials_Next-MultiShopping](https://developer.huawei.com/consumer/cn/codelabsPortal/carddetails/tutorials_Next-MultiShopping)\\n\\n## 一次开发，多端部署-购物应用 功能演示\\n\\n![phone](assets/phone.gif)\\n\\n---\\n\\n![foldable](assets/foldable.gif)\\n\\n---\\n\\n![tablet](assets/tablet.gif)\\n\\n\\n\\n## 一、响应式布局解决方案：断点系统\\n\\n在开发跨设备应用时，响应式布局是确保应用在不同尺寸设备上都能提供良好用户体验的关键。MultiShopping 项目中实现了一套优雅的断点系统（Breakpoint System），用于检测设备屏幕尺寸并自动调整 UI 布局。\\n\\n### 1.1 断点系统的核心实现\\n\\n断点系统的核心代码位于`common/src/main/ets/utils/BreakpointSystem.ets`文件中，主要包含两个关键类：\\n\\n#### BreakpointSystem 类\\n\\n该类负责监听设备屏幕尺寸变化，并将当前断点信息存储到 AppStorage 中：\\n\\n```typescript\\nexport class BreakpointSystem {\\n  private currentBreakpoint: string = \\"\\";\\n  private smListener?: mediaquery.MediaQueryListener;\\n  private mdListener?: mediaquery.MediaQueryListener;\\n  private lgListener?: mediaquery.MediaQueryListener;\\n\\n  private updateCurrentBreakpoint(breakpoint: string) {\\n    if (this.currentBreakpoint !== breakpoint) {\\n      this.currentBreakpoint = breakpoint;\\n      AppStorage.set<string>(\\n        BreakpointConstants.CURRENT_BREAKPOINT,\\n        this.currentBreakpoint\\n      );\\n    }\\n  }\\n\\n  public register() {\\n    this.smListener = mediaquery.matchMediaSync(BreakpointConstants.RANGE_SM);\\n    this.smListener.on(\\"change\\", this.isBreakpointSM);\\n    this.mdListener = mediaquery.matchMediaSync(BreakpointConstants.RANGE_MD);\\n    this.mdListener.on(\\"change\\", this.isBreakpointMD);\\n    this.lgListener = mediaquery.matchMediaSync(BreakpointConstants.RANGE_LG);\\n    this.lgListener.on(\\"change\\", this.isBreakpointLG);\\n  }\\n\\n  public unregister() {\\n    this.smListener?.off(\\"change\\", this.isBreakpointSM);\\n    this.mdListener?.off(\\"change\\", this.isBreakpointMD);\\n    this.lgListener?.off(\\"change\\", this.isBreakpointLG);\\n  }\\n}\\n```\\n\\n#### BreakPointType 类\\n\\n该类提供了一种便捷的方式，根据当前断点类型返回对应的 UI 配置值：\\n\\n```typescript\\nexport class BreakPointType<T> {\\n  options: BreakPointTypeOption<T>;\\n\\n  constructor(option: BreakPointTypeOption<T>) {\\n    this.options = option;\\n  }\\n\\n  getValue(currentBreakPoint: string): T {\\n    if (this.options.sm !== undefined && currentBreakPoint === \\"sm\\") {\\n      return this.options.sm as T;\\n    }\\n    if (this.options.md && currentBreakPoint === \\"md\\") {\\n      return this.options.md as T;\\n    } else {\\n      return this.options.lg as T;\\n    }\\n  }\\n}\\n```\\n\\n### 1.2 断点常量定义\\n\\n断点系统使用的常量定义在`common/src/main/ets/constants/BreakpointConstants.ets`文件中：\\n\\n```typescript\\nexport class BreakpointConstants {\\n  /**\\n   * 表示小型设备的断点\\n   */\\n  static readonly BREAKPOINT_SM: string = \\"sm\\";\\n\\n  /**\\n   * 表示中型设备的断点\\n   */\\n  static readonly BREAKPOINT_MD: string = \\"md\\";\\n\\n  /**\\n   * 表示大型设备的断点\\n   */\\n  static readonly BREAKPOINT_LG: string = \\"lg\\";\\n\\n  /**\\n   * 当前断点，用于查询设备类型\\n   */\\n  static readonly CURRENT_BREAKPOINT: string = \\"currentBreakpoint\\";\\n\\n  /**\\n   * 小型设备宽度范围\\n   */\\n  static readonly RANGE_SM: string = \\"(320vp<=width<520vp)\\";\\n\\n  /**\\n   * 中型设备宽度范围\\n   */\\n  static readonly RANGE_MD: string = \\"(520vp<=width<840vp)\\";\\n\\n  /**\\n   * 大型设备宽度范围\\n   */\\n  static readonly RANGE_LG: string = \\"(840vp<=width)\\";\\n}\\n```\\n\\n### 1.3 断点系统的工作原理\\n\\n#### 关键方法解析\\n\\n1. **mediaquery.matchMediaSync**：\\n\\n   - 这是鸿蒙系统提供的媒体查询 API，用于创建一个媒体查询监听器\\n   - 参数是一个媒体查询条件字符串，例如`\\"(320vp<=width<520vp)\\"`表示屏幕宽度在 320vp 到 520vp 之间\\n   - 返回一个`MediaQueryListener`对象，可用于监听媒体查询条件的变化\\n   - 与 Web 开发中的`window.matchMedia()`类似，但针对鸿蒙系统优化\\n\\n2. **listener.on(\\"change\\", callback)**：\\n\\n   - 为媒体查询监听器注册一个变化事件的回调函数\\n   - 当设备屏幕尺寸变化导致媒体查询条件结果发生变化时，会触发回调函数\\n   - 回调函数接收一个`MediaQueryResult`对象，其中`matches`属性表示当前是否匹配查询条件\\n   - 这种事件监听模式使断点系统能够实时响应设备尺寸变化\\n\\n3. **AppStorage.set**：\\n   - 将当前断点信息存储到应用的全局状态存储中\\n   - 使用`\\"currentBreakpoint\\"`作为键，确保全应用范围内可访问\\n   - 当断点变化时，所有使用`@StorageProp(\'currentBreakpoint\')`的组件都会自动更新\\n\\n#### 断点系统工作流程图\\n\\n![image-20250313084849947](assets/image-20250313084849947.png)\\n\\n\\n\\n### 1.4 断点系统的使用流程\\n\\n1. **初始化与注册**：\\n   在应用启动时（通常在入口页面的`aboutToAppear`生命周期函数中）初始化并注册断点系统：\\n\\n   ```typescript\\n   // SplashPage.ets\\n   @Entry\\n   @Component\\n   struct SplashPage {\\n     @StorageProp(\'currentBreakpoint\') currentBreakpoint: string = \'sm\';\\n     private breakpointSystem = new BreakpointSystem();\\n\\n     aboutToAppear() {\\n       this.breakpointSystem.register();\\n       // ...其他代码\\n     }\\n\\n     aboutToDisappear() {\\n       this.breakpointSystem.unregister();\\n       // ...其他代码\\n     }\\n   }\\n   ```\\n\\n2. **在组件中使用断点信息**：\\n   组件可以通过`@StorageProp`装饰器访问当前断点信息：\\n\\n   ```typescript\\n   @Component\\n   struct MyComponent {\\n     @StorageProp(\'currentBreakpoint\') currentBreakpoint: string = \'md\';\\n\\n     // ...组件代码\\n   }\\n   ```\\n\\n3. **根据断点调整 UI**：\\n   使用`BreakPointType`类根据当前断点返回对应的 UI 配置：\\n\\n   ```typescript\\n   Image($r(\\"app.media.ic_eshop\\")).width(\\n     new BreakPointType({\\n       sm: $r(\\"app.float.splash_image_size\\"),\\n       md: $r(\\"app.float.splash_image_size\\"),\\n       lg: $r(\\"app.float.splash_image_size_lg\\"),\\n     }).getValue(this.currentBreakpoint)\\n   );\\n   ```\\n\\n### 1.5 断点系统的优势\\n\\n1. **解耦与复用**：断点逻辑与 UI 组件解耦，可在整个应用中复用\\n2. **易于维护**：集中管理断点定义，便于统一修改\\n3. **类型安全**：通过泛型支持，确保类型安全\\n4. **使用简便**：提供简洁的 API，降低开发者使用成本\\n5. **实时响应**：基于事件监听机制，能够实时响应设备尺寸变化\\n6. **全局状态共享**：利用 AppStorage 机制，确保断点信息在全应用范围内一致\\n\\n## 二、工程级一多架构\\n\\nMultiShopping 项目采用了鸿蒙应用开发中常见的三层架构模式，实现了工程级的一多开发能力。\\n\\n### 2.1 架构层次\\n\\n项目架构分为三层：\\n\\n1. **公共能力层（common）**：\\n\\n   - 提供整个应用共享的基础组件、工具类和常量\\n   - 包含断点系统等跨设备适配的核心能力\\n   - 位于`common/`目录\\n\\n2. **基础特性层（features）**：\\n\\n   - 实现应用的各个功能模块\\n   - 每个功能模块相对独立，可单独开发和测试\\n   - 位于`features/`目录，包含多个子目录如`home/`、`personal/`等\\n\\n3. **产品定制层（product）**：\\n   - 针对不同设备类型（如手机、平板等）的具体产品实现\\n   - 整合公共能力层和基础特性层，构建完整产品\\n   - 位于`product/`目录，目前包含`phone/`子目录\\n\\n### 2.2 目录结构分析\\n\\n```\\nMultiShopping/\\n├── common/                 # 公共能力层\\n│   ├── src/main/ets/\\n│   │   ├── components/     # 公共UI组件\\n│   │   ├── constants/      # 公共常量定义\\n│   │   ├── utils/          # 公共工具类\\n│   │   └── viewmodel/      # 公共数据模型\\n│   └── ...\\n├── features/               # 基础特性层\\n│   ├── home/               # 首页功能模块\\n│   ├── personal/           # 个人中心功能模块\\n│   ├── shopcart/           # 购物车功能模块\\n│   ├── commoditydetail/    # 商品详情功能模块\\n│   └── ...\\n└── product/                # 产品定制层\\n    └── phone/              # 手机产品\\n        ├── src/main/ets/\\n        │   ├── pages/      # 页面定义\\n        │   ├── entryability/ # 应用入口\\n        │   └── ...\\n        └── ...\\n```\\n\\n### 2.3 层间依赖关系\\n\\n- **依赖方向**：产品层 → 特性层 → 公共层\\n- **依赖管理**：通过`oh-package.json5`文件管理模块间依赖\\n\\n### 2.4 工程级一多架构的优势\\n\\n1. **代码复用**：公共能力层提供跨设备共享的基础能力，减少重复开发\\n2. **职责分离**：各层职责明确，便于团队协作开发\\n3. **灵活适配**：产品层可针对不同设备特性进行定制，提供最佳用户体验\\n4. **可维护性**：模块化设计使代码更易于维护和扩展\\n5. **并行开发**：不同团队可以并行开发不同层次或模块\\n\\n## 总结\\n\\nMultiShopping 项目通过断点系统实现了优雅的响应式布局，通过三层架构实现了工程级的一多开发能力。这些设计不仅提高了开发效率，也确保了应用在不同设备上的一致性和良好体验。\\n\\n对于鸿蒙应用开发者而言，这些设计模式和实践经验具有很高的参考价值，可以帮助开发者构建高质量的跨设备应用。通过学习和借鉴 MultiShopping 项目的实现，开发者可以更好地掌握鸿蒙应用开发的最佳实践。"}'),r={name:"万少带你精读鸿蒙codelabs/01-万少带你精读鸿蒙codelabs 一多界面适配和三层架构/01-万少带你精读鸿蒙codelabs 一多界面适配和三层架构.md"};function k(d,s,o,E,c,g){return n(),a("div",null,[...s[0]||(s[0]=[p("",45)])])}const b=i(r,[["render",k]]);export{u as __pageData,b as default};
